  #[local] Abbreviation pframe := (nt_pframe sp parser key w1 w2).
  #[local] Abbreviation fbase := (nt_fbase fx).
  #[local] Abbreviation SPF := (sp_facts C).
  #[local] Abbreviation BCF := (bc_facts C).
  #[local] Abbreviation VF := (val_facts C).
  #[local] Ltac ctx := ntctx_pose C.

  #[local] Abbreviation core := (@HNtAU1.core AC L MI ST NEW_STACK DEL_STACK A0 s R0 model0 sp parser key w1 w2).

  Record rcall (p : Z) (A : AS MI) (M : mem) (model : Model) (R : bvmap 5 word) : Prop := RCALL {
    rc_ai : ainv MI A M model;
    rc_ms : mstd model;
    rc_fs : m_fs model = m_fs model0;
    rc_fds : m_fds model = m_fds model0;
    rc_sx : sx_inv ST s M;
    rc_regs : base_ok R;
    rc_s7 : getr R 23%bv = Z_to_bv 64 key;
    rc_s11 : getr R 27%bv = Z_to_bv 64 p;
    rc_s6 : getr R 22%bv = Z_to_bv 64 (bseq_next bc);
    rc_s10 : getr R 26%bv = Z_to_bv 64 w3;
    rc_a0 : getr R 10%bv = Z_to_bv 64 (8 * bseq_next bc);
    rc_ra : getr R 1%bv = Z_to_bv 64 NT_NEW2R;
    rc_frame : pframe M;
    rc_def0 : defined M sp 8;
    rc_defw : defined M (sp - NTS) NTS;
    rc_spill : cell8 SEGS M sp (2 ^ 60);
    rc_p0 : 0 < p; rc_pc : p + 32 <= alloc_ceiling; rc_pal : p mod 16 = 0;
    rc_plive : In (p, 32) (live MI A);
    rc_pnew : ~ In p (map fst (live MI A0));
    rc_nh : cell8 SEGS M (p + 8) key;
    rc_nk : cell4 SEGS M (p + 16) key;
    rc_pdef : defined M p 32;
    rc_eff : eff MI A0 A M0 M W (fun a => p <= a < p + 32 \/ sp <= a < sp + 8);
    rc_ladd : live_add p 32 (live MI A0) (live MI A);
    rc_U : umapx MI 32 (nval32 SEGS) A M obj bl bc ents;
    rc_grow : bc = 0 \/ Zlength ents = bc;
    rc_roc : ro_clear L M
  }.

  Definition gregs (p : Z) (R : bvmap 5 word) : Prop :=
    base_ok R /\ getr R 23%bv = Z_to_bv 64 key /\ getr R 27%bv = Z_to_bv 64 p /\ getr R 24%bv = Z_to_bv 64 bc
    /\ getr R 26%bv = Z_to_bv 64 w3 /\ getr R 6%bv = Z_to_bv 64 (2 ^ 60).

  Lemma gregs_upd : forall p R r v, gregs p R -> ~ In r [2; 3; 4; 6; 8; 9; 18; 19; 20; 21; 23; 24; 25; 26; 27]%bv -> gregs p (regupd R r v).
Proof using L R0 sp parser key bc w3.
