  Ltac gregs_from HR' G :=
    let B := fresh in let Q23 := fresh in let Q27 := fresh in let Q24 := fresh in let Q26 := fresh in let Q6 := fresh in
    destruct G as (B & Q23 & Q27 & Q24 & Q26 & Q6); unfold gregs;
    split; [nt_base_from HR' B|];
    split; [let Q := fresh in rreg HR' 23%bv Q; exact Q|];
    split; [let Q := fresh in rreg HR' 27%bv Q; exact Q|];
