    split; [let Q := fresh in rreg HR' 26%bv Q; exact Q| let Q := fresh in rreg HR' 6%bv Q; exact Q].

#[local] Definition HTHNtRU1_0 : list (reg * expr) := [(27%bv, EVar 32); (8%bv, EVar 33); (24%bv, EVar 34); (23%bv, EVar 35); (10%bv, EVar 36); (11%bv, EVar 37); (26%bv, EVar 38); (6%bv, EVar 39); (2%bv, EVar 40)].
  Lemma phaseR1 : forall (fx1 : FPState) p A M model R,
    core p A M model R -> getr R 24%bv = Z_to_bv 64 bc -> getr R 26%bv = Z_to_bv 64 w3 -> getr R 6%bv = Z_to_bv 64 (2 ^ 60) ->
    fbase fx1 -> fholds fx1 14%bv (ieee (Zlength ents + 1)) -> fholds fx1 15%bv one32 ->
    (bc = 0 \/ Zlength ents = bc) ->
    eff MI A0 A M0 M W (fun a => p <= a < p + 32) -> live_add p 32 (live MI A0) (live MI A) ->
    umapx MI 32 (nval32 SEGS) A M obj bl bc ents -> ro_clear L M ->
    (forall (fx2 : FPState) M' R', fbase fx2 -> rcall p A M' model R' -> srealizes SEGS (cfg fx2 R' NT_NEWE M' model) K) ->
    srealizes SEGS (cfg fx1 R NT_GROW M model) K.
Proof using AC L MI ST NEW_STACK DEL_STACK fx A0 s R0 M0 model0 sp parser key bl bc w1 w2 w3 val ents K C.
Ltac scR DEF0 Hland :=
      split_scs;
      lazymatch goal with
      | |- sc_denot _ _ _ (SCStoreOk _ _) => sc_so; eapply (defined_sub _ _ _ _ _ DEF0); lia
      | |- sc_denot _ _ _ (SCFlat _ _) => sc_fl
      | |- sc_denot _ _ _ (SCBr _ _ _ _) =>
          cbn [sc_denot]; evs; nadd; repeat match goal with |- context [?x + -1] => change (x + -1) with (x - 1) end;
          rewrite ?w_and by lia; rewrite ?Hland; rewrite ?br_eq, ?br_ne, ?br_geu, ?br_ltu by lia; bool_lia
